const regionNames={'01':'Stockholm','03':'Uppsala','04':'Sörmland','05':'Östergötland','06':'Jönköpings län','07':'Kronoberg','08':'Kalmar län','09':'Gotland','10':'Blekinge','12':'Skåne','13':'Halland','14':'Västra Götaland','17':'Värmland','18':'Örebro län','19':'Västmanland','20':'Dalarna','21':'Gävleborg','22':'Västernorrland','23':'Jämtland Härjedalen','24':'Västerbotten','25':'Norrbotten'};
const $=id=>document.getElementById(id);let municipalities=[];const municipality=$('municipality');
fetch('municipalities.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{municipalities=data.sort((a,b)=>a.name.localeCompare(b.name,'sv'));fillMunicipalities();}).catch(()=>{$('region').textContent='Municipality list could not load. Reload to try again. Stockholm is selected.'});
function fillMunicipalities(){const selected=municipality.value||'0180';const q=$('search').value.trim().toLocaleLowerCase('sv');const rows=municipalities.filter(m=>m.name.toLocaleLowerCase('sv').includes(q));municipality.replaceChildren(...rows.map(m=>new Option(m.name,m.code)));if(rows.some(m=>m.code===selected))municipality.value=selected;if(!rows.length){municipality.add(new Option('No matching municipality',''));municipality.disabled=true}else municipality.disabled=false;updateLocation();}
$('search').addEventListener('input',fillMunicipalities);municipality.addEventListener('change',updateLocation);
function updateLocation(){$('region').textContent=municipality.value?'Region '+regionNames[municipality.value.slice(0,2)]:'Try another municipality name.';renderResult();}
const answers={citizen:'no',age:'',registered:'',group:'',years:''};
function question(name,title,choices){return `<fieldset><legend>${title}</legend>${choices.map(([value,label])=>`<label class="choice"><input type="radio" name="${name}" value="${value}" ${answers[name]===value?'checked':''}>${label}</label>`).join('')}</fieldset>`;}
function renderQuestions(){
 $('eligibility').innerHTML=question('age','Will you be 18 or older on 13 September 2026?',[['yes','Yes'],['no','No']])+question('registered','Are you registered (folkbokförd) in the selected municipality?',[['yes','Yes'],['no','No']])+(answers.citizen==='no'?question('group','Are you a citizen of an EU country, Norway or Iceland?',[['yes','Yes'],['no','No / stateless']])+(answers.group==='no'?question('years','Will you have been registered in Sweden for at least 3 consecutive years before election day?',[['yes','Yes'],['no','No']]):''):'');
 renderResult();
}
document.addEventListener('change',e=>{if(e.target.type==='radio'&&e.target.name in answers){answers[e.target.name]=e.target.value;if(['citizen','group'].includes(e.target.name))renderQuestions();else renderResult();}});
function renderResult(){
 if(typeof answers==='undefined')return;
 let title='A few checks before you continue';let body='Answer the eligibility questions above. You can explore the information below at any time.';
 if(answers.age==='no'){title='You need to be 18 by election day';body='You would not be eligible for these elections in 2026. You can still explore how they work.';}
 else if(answers.age==='yes'&&answers.registered==='no'){title='Check your registered address';body='Your local elections follow the population register. Select the municipality where you are registered. Swedish citizens who have previously been registered in Sweden may still qualify for the Riksdag election; check with Valmyndigheten.';}
 else if(municipality.value&&answers.age==='yes'&&answers.registered==='yes'){
  const gotland=municipality.value==='0980';
  if(answers.citizen==='yes'){title=gotland?'Your likely elections: Riksdag + Gotland council':'Your likely elections: Riksdag + municipality + region';body='Based on your answers, you meet the general eligibility conditions. Check your voting card to confirm.';}
  else if(answers.group==='yes'||(answers.group==='no'&&answers.years==='yes')){title=gotland?'Your likely election: Gotland council':'Your likely elections: municipality + region';body='Based on your answers, you meet the general local voting conditions. Swedish citizenship is required for the Riksdag election. Check your voting card to confirm.';}
  else if(answers.group==='no'&&answers.years==='no'){title='The three-year registration requirement applies';body='Based on your answers, you do not yet meet the local voting conditions. The rule concerns consecutive population registration, not just time spent in Sweden.';}
  if(gotland)body+=' Gotland has one council for municipal and regional responsibilities, with no separate regional ballot.';
 }
 $('result').innerHTML=`<strong>${title}</strong>${body}<p class="small">The electoral roll uses population-register information from 30 days before election day. If your circumstances changed or you are unsure, check with Valmyndigheten.</p>`;
 if(typeof renderParties==='function'&&typeof parties!=='undefined')renderParties();
}
